package net.civeira.phylax.common.infrastructure.mail;

import java.util.concurrent.ConcurrentHashMap;

import io.vertx.ext.mail.MailConfig;
import io.vertx.ext.mail.StartTLSOptions;
import io.vertx.mutiny.core.Vertx;
import io.vertx.mutiny.ext.mail.MailClient;
import jakarta.annotation.PreDestroy;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;

/**
 * Cache of Vert.x {@link MailClient} instances keyed by SMTP configuration.
 *
 * Each unique combination of host, port and login gets one shared client. This avoids the overhead
 * of creating a new connection pool per message while supporting per-tenant SMTP settings at
 * runtime. Clients are closed gracefully on application shutdown.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class DynamicMailClientCache {

  private final Vertx vertx;
  private final ConcurrentHashMap<String, MailClient> clients = new ConcurrentHashMap<>();

  public MailClient clientFor(MailConfiguration config) {
    return clients.computeIfAbsent(cacheKey(config), _ -> createClient(config));
  }

  private MailClient createClient(MailConfiguration config) {
    MailConfig mailConfig = new MailConfig()
        .setHostname(config.getSmtpHost())
        .setPort(config.getSmtpPort())
        .setUsername(config.getSmtpLogin())
        .setPassword(config.getSmtpPass())
        .setStarttls(config.isUseTtls() ? StartTLSOptions.REQUIRED : StartTLSOptions.DISABLED)
        .setConnectTimeout(config.getConnectionTimeout() * 1000);
    return MailClient.create(vertx, mailConfig);
  }

  private String cacheKey(MailConfiguration config) {
    return config.getSmtpHost() + ":" + config.getSmtpPort() + ":" + config.getSmtpLogin();
  }

  @PreDestroy
  void shutdown() {
    clients.values().forEach(MailClient::closeAndAwait);
    clients.clear();
  }
}
